design('sections',1,'Who chose the rule, and how?','Separate writing a rule, fitting a rule and using the finished rule.',[g('Start with the same answer',[start],'example'),g('Retrieve the measurement boundary',[14,5,8]),g('By the end, you can…',[1,2,3],'prompts')])
design('sections',2,'Two routes to the same sorting threshold','Read the task’s label convention before comparing rules.',[g('Meet the two paper sorters',[13],'example'),g('Choosing is different from applying',[14]),g('Whose labels are these?',[15]),g('Describe before you explain',[6,9],'prompts')])
scope=add('sections',3,text=w['sections'][12]['blocks'][11]['text'])
