gallery={'type':'gallery','layout':'reading-cards','reading_addition':'week4-connected-reading','cells':[[copy.deepcopy(w['sections'][3]['blocks'][3+i]),copy.deepcopy(w['sections'][3]['blocks'][7+i])] for i in range(4)]};w['sections'][3]['blocks'].append(gallery);idx=len(w['sections'][3]['blocks'])-1
design('sections',4,'Compare evidence about the rule’s origin','Simple and complicated do not tell you whether a rule was fitted.',[g('Four cases, paired with their evidence',[idx],'cards'),g('Discuss the confusing pair',[12],'prompts'),g('Keep the distinction clear',[11],'example')])
