design('sections',6,'Choose a pebble rule using labelled examples','Compare the candidates on the supplied labels, then use the chosen rule on a new measurement.',[g('The fictional fitting task',[18,20,21],'example'),g('Trace selection and the later prediction',[trace]),g('Compare the candidate errors',[errors]),g('Explain why boundary 5 was selected',[26]),g('Predict at the boundary',[predict],'prompts'),g('Check the changed prediction',[change],'example',True),g('State the limit of zero fitting errors',[28],'example'),g('Explain which step used labels',[29],'prompts')])
design('sections',7,'Keep a mismatch instead of hiding it','A fitted rule can disagree with a new supplied label.',[g('Inspect the new-card disagreement',[11],'example'),g('Keep a prediction separate from an action',[12]),g('Repair two tempting claims',[5,7,9,13],'prompts')])
practice=add('sections',8,'For W2, use widths 1, 3, 5 and 7 cm with labels narrow, narrow, wide and wide. For each candidate, predict wide when width is at least the threshold. Write a prediction for every row, then compare it with the supplied label. The size words are the labels of this task, not universal definitions.')
design('sections',8,'Practise: predict every row before counting errors','Use the W2 comparison as one supported attempt, then explain why an unseen check must stay separate.',[g('The new practice record',[practice],'example'),g('Complete and check the comparison',[15,16,12],'steps'),g('Do not turn a final check into fitting data',[13]),g('Explain and switch roles',[17]),g('Challenge “a learned rule cannot be simple”',[19,20],'prompts'),g('Explain the pictured label use',[22,23,24])])
lab=add('sections',9,'Use these fictional evidence cards. A motion light follows a written instruction: motion=yes → ON, motion=no → OFF, missing reading → request a sensor check. An animal recognizer was fitted using labelled photographs; it displays CAT for one supplied new image. A robot vacuum turns left, but its process notes are missing. These are given facts, not results from a real device test.')
lab2=add('sections',9,'Before discussion, predict which cases have evidence of fitting. Trace the motion rule for yes, no and missing. For the recognizer, point to the training fact; CAT alone would not establish how it was obtained or whether it is correct. For the vacuum, write what evidence you would request instead of guessing. Record this as a paper trace and evidence comparison.')
design('sections',9,'Investigate: compare the builder’s notes','Use mechanism evidence to distinguish a written instruction, fitting and an unknown process.',[g('Your supplied case cards',[lab],'example'),g('Predict, trace and compare',[lab2,6,7,8],'steps'),g('Keep a normal and missing-input record',[9,12])])
design('sections',10,'Choose a stronger fitting challenge','Choose one next step that tests your current explanation.',[g('Pick a useful challenge',list(range(4,11)),'prompts')],True)
design('sections',11,'Record where your sorter’s rule came from','Keep the written design choice or candidate-error record beside the finished rule.',[g('This week’s project decision',[4,14],'example'),g('Plan evidence and a separate check',[5,6,7,8,9],'prompts'),g('Avoid the complexity shortcut',[11])])
