for role,n in [('sections',17),('workbook',20)]:
 design(role,n,'Extra practice: fitting pictures and feedback','Try before opening each explanation. Keep these supported questions separate from the independent case.',[g('First supported question',list(range(1,10)),'prompts'),g('Check the first explanation',[10],'example',True),g('Changed-boundary question',list(range(11,18)),'prompts'),g('Check the boundary',[18],'example',True),g('Repair and save',[20,21,23]+([24] if role=='workbook' else []))],True)
design('sections',18,'Reference: six-picture fitting journey','Use the picture that answers your current question; the main trace is already in the lesson.',[g(w['sections'][17]['blocks'][4*i]['text'],list(range(4*i+1,4*i+4))) for i in range(6)],True)

