design('teacher',2,'Teach how the rule was obtained','Model a full prediction list before an error count, then distinguish fitting evidence from later performance.',[g('Introduce the two routes to a threshold',[22,23,24],'example'),g('Explain the boundary and human choices',[25,26,15]),g('Model the pebble fitting task',[base,facts,procedure,ttrace,terrors,reason],'example'),g('Change only the prediction input',[changed,changed+1,changed+2],'steps'),g('Limit the training result',[limit]),g('Show that equal scores can hide different predictions',[31,32,33],'example'),g('Use the picture deliberately',[35,53])])
design('teacher',3,'Guide row-by-row predictions, then remove help','Collect each learner’s comparison before accepting the error count.',[g('Prompt before revealing the key',[16],'example'),g('Expected reasoning and fading help',[17,18]),g('Check the simplicity misconception',[20,21,22],'example'),g('Check label use and the changed boundary',[24,26,27,28]),g('Keep each learner explaining',[7,8,10],'prompts')])
tlab=add('teacher',4,'Use the student evidence cards: the motion light has an explicit three-way rule, the animal recognizer has a supplied fitting history, and the vacuum has no process notes. Expected motion trace: yes → ON, no → OFF, missing → request a sensor check. The recognizer’s fitting history establishes a learned process; its displayed CAT alone establishes neither origin nor correctness. Vacuum mechanism remains unknown. Reserve the new length classifier for the individual first attempt.')
design('teacher',4,'Run the mechanism-evidence comparison','Use supplied notes and distinguish a paper trace from a real classifier test.',[g('Supplied cases and answer guidance',[tlab],'example'),g('Run and record the comparison',[3,4,5,6],'steps'),g('Keep an inspectable record',[10]),g('Diagnose the first misunderstanding',[15,16,17],'cards'),g('Choose support from the response',[19,20])])
design('teacher',5,'Assess the new length classifier','Use this selected key only after the first independent attempt.',[g('Selected independent question and answer',[31,33],'example'),g('Judge explanation, trace and limits',[34,35]),g('Give one usable repair action',[37]),g('W1: execute the boundary',[16,17],'example'),g('W2: compare fitting errors',[19,20],'example'),g('W3: expose the tie',[22,23],'example'),g('W5: keep the final check honest',[28,29],'example')])
design('teacher',6,'Connect, adapt and revisit','Keep the fitting record and revisit the distinction on a changed task.',[g('Project evidence to retain',[2,3,20]),g('Support without losing the reasoning',[5,11,12]),g('Plan the delayed check',[15,16,17,18]),g('Bridge to numerical pictures',[7,9,13])])
design('teacher',7,'Reference: alternative planning checklist','Use this to inspect the main route rather than repeating a second lesson.',[g('Preparation and schedule',[0,1,2]),g('Practice and assessment reminders',list(range(3,13)))],True)
