design('teacher',9,'Reference: teach with the six pictures','Choose the graphic for the teaching move and connect it to the explanation.',[g(w['teacher'][8]['blocks'][1+5*i]['text'],list(range(2+5*i,6+5*i))) for i in range(6)],True)
main=[(1,'Recall · Measurements and mechanisms','Retrieve both earlier ideas before checking your notes.'),(12,'W1 · Execute the boundary','Apply the stated comparison before selecting any new rule.'),(13,'W2 · Compare the candidate errors','Write every prediction before counting disagreements.'),(14,'W3 · Make a tie visible','Use the supplied fitting examples and identify a new input that separates the candidates.'),(16,'W5 · Keep the check honest','Explain when a revealed check case becomes development data.'),(4,'W4 · Fit a new length classifier','Keep one first attempt before hints or teacher feedback.'),(9,'Project · Keep the rule’s origin','Record the written design or candidate-error evidence.'),(17,'Feedback · Repair and return','Keep your original attempt and a later changed-case check.'),(10,'Finish · Judge the evidence in your work','Point to a prediction list, fitting choice and limit.')]
for n,title,purpose in main:
 groups=([g('Retrieve and explain',[0,2,3,5,6],'prompts')] if n==1 else [g('Read and explain independently',[1,2],'example'),g('Keep a fair record',[3])] if n==4 else [g('Your project decision',[0,1,2],'prompts')] if n==9 else [g('Your evidence record',[0,1])])
 design('workbook',n,title,purpose,groups)
