for n,(title,purpose) in refs.items():
 s=w['workbook'][n-1];groups=([g(s['blocks'][5*i]['text'],list(range(5*i+1,5*i+5))) for i in range(6)] if n==21 else [g('Use this when helpful',list(range(len(s['blocks']))))]);design('workbook',n,title,purpose,groups,True)
overviews={
 'sections':('Choose the rule. Then use it.','Compare two ways to obtain a sorter rule, fit a pebble boundary, practise with visible error counts and try a new length classifier.','Separate fitting evidence from prediction input and a genuinely new check.',[1,2,3,4,6,7,8,9,14,11,16,5,10,12,13,15,17,18],[('Notice',2),('Separate stages',3),('Fit a rule',6),('Practise',8),('Try alone',14),('Build & reflect',11)]),
 'teacher':('Teach fitting as an inspectable procedure.','Model the candidate predictions and errors, separate fitting from execution, and reserve the new length classifier for independent evidence.','Look for complete prediction lists, justified selection and a limited claim.',list(range(1,10)),[('Prepare',1),('Explain',2),('Guide',3),('Investigate',4),('Assess',5),('Return',6)]),
 'workbook':('One connected fitting record.','Execute a rule, compare candidates, inspect a tie, protect the final check and fit a different classifier.','Keep predictions, labels, error counts and the reason for the chosen rule.',[1,12,13,14,16,4,9,17,10,2,3,5,6,7,8,11,15,18,19,20,21],[('Recall',1),('Execute',12),('Fit',13),('Inspect a tie',14),('Check honestly',16),('Try alone',4)])}
